                setHasApiKey(false);
            }
        }
    }
  };

  // Memoize form state for useEffect dependency to prevent unnecessary re-saves
  const formState = useMemo(() => ({
    objective,
    audienceAction,
    keyMessage,
    context,
    aspectRatios,
    imageSize,
    numberOfImages,
    styleGuideContent,
    attachStyleGuideDirectly,
