              let newIndex = variant.currentHistoryIndex;
              if (direction === 'prev') {
                  newIndex = Math.max(0, newIndex - 1);
              } else {
                  newIndex = Math.min(variant.history.length - 1, newIndex + 1);
              }
              return {
                  ...c,
                  variants: {
                      ...c.variants,
                      [ratio]: { ...variant, currentHistoryIndex: newIndex }
                  }
              };
          }
          return c;
