    }));

  }, [adCreatives, assets]);


  const handleRegenerateVariant = useCallback(async (id: string, ratio: string, newPrompt: string, newImageSize: string) => {
    const targetCreative = adCreatives?.find(c => c.id === id);
    if (!targetCreative) return;

    setError(null);

    // Set generating state
    setAdCreatives(prev => 
      prev!.map(c => {
          if (c.id === id) {
